package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.space.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.neoforged.neoforge.gametest.PrefixGameTestTemplate;
import java.util.*;
@PrefixGameTestTemplate(false)
public final class LunarOrbitGameTests {
 @GameTest(template="empty",templateNamespace="around_planet",batch="surfaceMoonNetwork",timeoutTicks=40)
 public static void surfaceSkyReceivesTheSameWarpedModelWithoutLoadingTerrain(GameTestHelper h){var level=h.getLevel();var data=SpaceOrbitData.get(level.getServer());var old=data.system();try{var sys=new CelestialSystem(20000,4e9,1234);data.system(sys);int chunks=level.getChunkSource().getLoadedChunksCount();var packet=io.github.astelev.around_planet.network.CelestialSkyPayload.sample(level);var buf=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),level.registryAccess());try{var codec=io.github.astelev.around_planet.network.CelestialSkyPayload.CODEC;codec.encode(buf,packet);h.assertTrue(codec.decode(buf).equals(packet),"Surface sky lost celestial parameters over network");}finally{buf.release();}data.system(sys.warp(2400));h.assertTrue(io.github.astelev.around_planet.network.CelestialSkyPayload.sample(level).system().equals(sys.warp(2400)),"Surface sky retained pre-warp model");h.assertTrue(level.getChunkSource().getLoadedChunksCount()==chunks,"Surface ephemeris loaded terrain");h.succeed();}finally{data.system(old);}}

 @GameTest(template="empty",templateNamespace="around_planet",batch="lunarPersistence",timeoutTicks=100)
 public static void lunarWarpAndTargetSurviveSaveWithoutLoadingAnyShip(GameTestHelper h){var data=new SpaceOrbitData();var sys=new CelestialSystem(20000,4e9,0);data.system(sys);var id=UUID.randomUUID();long now=1000;double r=sys.moonRadius()*2;var path=new SpaceTrajectory(CelestialSystem.MOON,now,new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(sys.moonMu()/r),0)),sys.moonMu());data.put(id,path);data.target(id,CelestialSystem.MOON_ID);data.previewDepth(id,12);data.forecastTurns(id,5);boolean rejected=false;try{data.put(CelestialSystem.MOON_ID,path);}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Moon was accepted as an editable vessel orbit");var node=new ManeuverNode(UUID.randomUUID(),now+10000,5,0,0,.15);data.maneuver(id,node);data.warp(now,2400);var copy=SpaceOrbitData.load(data.save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(copy.forecastTurns(id)==5&&copy.previewDepth(id)==12&&copy.system().clockTicks()==2400&&copy.target(id).orElseThrow().equals(CelestialSystem.MOON_ID),"Lunar ephemeris/target did not persist");h.assertTrue(copy.get(id).orElseThrow().primary().equals(CelestialSystem.MOON)&&copy.sample(id,now).position().subtract(path.at(now+2400).position()).length()<1e-7,"Dormant lunar coast lost during warp");h.assertTrue(copy.system().moon(now).position().subtract(sys.moon(now+2400).position()).length()<1e-7&&copy.maneuvers(id).getFirst().warningTicks(-1)==3,"Moon and ship clocks diverged");h.succeed();}
}
